public class InitializerBindProbe {
    private static List<String> observed = new List<String>();
    private static String sharedName = 'OwnedInitializerNoMatch';
    static {
        for (Account unused : [SELECT Id FROM Account WHERE Id = null WITH SYSTEM_MODE]) {}
        String scalarName = 'OwnedInitializerNoMatch';
        List<Account> scalarRows = [SELECT Id FROM Account WHERE Name = :scalarName WITH SYSTEM_MODE];
        observed.add('scalar:' + scalarRows.size());
        List<String> names = new List<String>{scalarName};
        Integer count = 0;
        for (Account row : [SELECT Id FROM Account WHERE Name IN :names WITH SYSTEM_MODE]) count++;
        observed.add('list:' + count);
        {
            Set<Id> ids = new Set<Id>();
            List<Account> nestedRows = [SELECT Id FROM Account WHERE Id IN :ids WITH SYSTEM_MODE];
            observed.add('nested:' + nestedRows.size());
        }
    }
    static /* executable scope */ {
        List<Account> fieldRows = [SELECT Id FROM Account WHERE Name = :sharedName WITH SYSTEM_MODE];
        observed.add('field:' + fieldRows.size());
    }
    public static String observe() { return String.join(observed, '|'); }
}

